          if (this._isPictureInPicture(i) || !this._desiredPlaying[i] || !this._deviceProfile.isMobile) return;
          if ((!this._pageVisible || this._tileVisible[i] === false) && this._cards[i]===camera)
            this._stopCamera(i,true,true);
